using System.Net;
using System.Net.Http.Json;
using System.Text.Json;
using System.Text.Json.Nodes;

namespace Acme.Ticketing.Tests;

[TestClass]
public class BoxOfficeTests : ApiTestBase
{
    private static JsonObject Address() => new() { ["street"] = "1 Main", ["city"] = "Paris", ["postalCode"] = "75001" };

    private async Task<JsonNode> CreateVenue(string name = "Hall", int capacity = 100) =>
        (await PostAsync<JsonNode>("/venues", new { name, address = Address(), capacity }))!;

    private async Task<JsonNode> CreateShow(Guid venueId, int status = 1, DateTime? startsAt = null, int quota = 10, decimal price = 12.5m) =>
        (await PostAsync<JsonNode>("/shows", new
        {
            title = "Concert",
            startsAt = startsAt ?? DateTime.UtcNow.AddDays(10),
            status,
            venueId,
            ticketTiers = new[] { new { name = "Gold", price, quota } },
        }))!;

    private static Guid Id(JsonNode n) => n["id"]!.GetValue<Guid>();

    private Task<HttpResponseMessage> Book(Guid showId, string tier = "Gold", int quantity = 2, string email = "a@b.c") =>
        Client.PostAsJsonAsync("/box-office/book", new { showId, tier, customerEmail = email, quantity });

    [TestMethod]
    public async Task Book_Succeeds_And_UpdatesSold()
    {
        var venue = await CreateVenue();
        var show = await CreateShow(Id(venue));
        var response = await Book(Id(show), quantity: 3);
        Assert.AreEqual(HttpStatusCode.OK, response.StatusCode, await response.Content.ReadAsStringAsync());
        var booking = (await response.Content.ReadFromJsonAsync<JsonNode>())!;
        Assert.AreEqual(37.5m, booking["totalPrice"]!.GetValue<decimal>());
        Assert.AreEqual("Gold", booking["tier"]!.GetValue<string>());

        var got = (await Client.GetFromJsonAsync<JsonNode>($"/shows/{Id(show)}"))!;
        Assert.AreEqual(3, got["ticketTiers"]![0]!["sold"]!.GetValue<int>());
        Assert.IsFalse(got["isSoldOut"]!.GetValue<bool>());

        var bookings = (await Client.GetFromJsonAsync<JsonNode>("/bookings"))!;
        Assert.AreEqual(1, bookings["totalCount"]!.GetValue<int>());
        Assert.AreEqual(HttpStatusCode.OK, (await Client.GetAsync($"/bookings/{Id(booking)}")).StatusCode);
    }

    [TestMethod]
    public async Task Book_Refusals()
    {
        var venue = await CreateVenue();
        var show = await CreateShow(Id(venue), quota: 5);
        await AssertInvalidAsync(await Book(Id(show), quantity: 0), "Quantity");
        await AssertInvalidAsync(await Book(Id(show), quantity: 11), "Quantity");
        await AssertInvalidAsync(await Book(Id(show), email: "nope"), "CustomerEmail");
        Assert.AreEqual(HttpStatusCode.NotFound, (await Book(Guid.NewGuid())).StatusCode);
        Assert.AreEqual(HttpStatusCode.BadRequest, (await Book(Id(show), tier: "Silver")).StatusCode);
        Assert.AreEqual(HttpStatusCode.Conflict, (await Book(Id(show), quantity: 6)).StatusCode);
        Assert.AreEqual(HttpStatusCode.OK, (await Book(Id(show), quantity: 5)).StatusCode);
        Assert.AreEqual(HttpStatusCode.Conflict, (await Book(Id(show), quantity: 1)).StatusCode);

        var got = (await Client.GetFromJsonAsync<JsonNode>($"/shows/{Id(show)}"))!;
        Assert.IsTrue(got["isSoldOut"]!.GetValue<bool>());

        var draft = await CreateShow(Id(venue), status: 0);
        Assert.AreEqual(HttpStatusCode.Conflict, (await Book(Id(draft))).StatusCode);
        var past = await CreateShow(Id(venue), startsAt: DateTime.UtcNow.AddDays(-1));
        Assert.AreEqual(HttpStatusCode.Conflict, (await Book(Id(past))).StatusCode);
    }

    [TestMethod]
    public async Task Show_Tiers_Sync_IgnoresSold_And_Capacity()
    {
        var venue = await CreateVenue(capacity: 20);
        var show = await CreateShow(Id(venue), quota: 10);
        await Book(Id(show), quantity: 2);
        var tierId = show["ticketTiers"]![0]!["id"]!.GetValue<Guid>();

        object Body(object[] tiers) => new { title = "T", startsAt = DateTime.UtcNow.AddDays(3), status = 1, venueId = Id(venue), ticketTiers = tiers };

        var ok = await Client.PutAsJsonAsync($"/shows/{Id(show)}", Body([
            new { id = tierId, name = "Gold", price = 1m, quota = 12, sold = 0 },
            new { name = "Bronze", price = 1m, quota = 8 }]));
        Assert.AreEqual(HttpStatusCode.OK, ok.StatusCode, await ok.Content.ReadAsStringAsync());
        var updated = (await ok.Content.ReadFromJsonAsync<JsonNode>())!;
        Assert.AreEqual(2, updated["ticketTiers"]!.AsArray().Count);
        Assert.AreEqual(2, updated["ticketTiers"]![0]!["sold"]!.GetValue<int>());

        var tooMany = await Client.PutAsJsonAsync($"/shows/{Id(show)}", Body([new { id = tierId, name = "Gold", price = 1m, quota = 21 }]));
        await AssertInvalidAsync(tooMany, "TicketTiers");

        var removed = await Client.PutAsJsonAsync($"/shows/{Id(show)}", Body([new { id = tierId, name = "Gold", price = 1m, quota = 5 }]));
        Assert.AreEqual(1, (await removed.Content.ReadFromJsonAsync<JsonNode>())!["ticketTiers"]!.AsArray().Count);
    }

    [TestMethod]
    public async Task Deletions_And_Validation()
    {
        var venue = await CreateVenue();
        var dup = await Client.PostAsJsonAsync("/venues", new { name = "Hall", address = Address(), capacity = 1 });
        Assert.AreEqual(HttpStatusCode.Conflict, dup.StatusCode);
        var longName = await Client.PostAsJsonAsync("/venues", new { name = new string('x', 101), address = Address(), capacity = 1 });
        await AssertInvalidAsync(longName, "Name");

        var show = await CreateShow(Id(venue));
        var unknownVenue = await Client.PostAsJsonAsync("/shows", new { title = "x", startsAt = DateTime.UtcNow, status = 0, venueId = Guid.NewGuid(), ticketTiers = Array.Empty<object>() });
        await AssertInvalidAsync(unknownVenue, "VenueId");
        var badStatus = await Client.PostAsJsonAsync("/shows", new { title = "x", startsAt = DateTime.UtcNow, status = 9, venueId = Id(venue), ticketTiers = Array.Empty<object>() });
        Assert.AreEqual(HttpStatusCode.BadRequest, badStatus.StatusCode);

        var withShows = (await Client.GetFromJsonAsync<JsonNode>($"/venues/{Id(venue)}"))!;
        Assert.AreEqual(1, withShows["shows"]!.AsArray().Count);
        Assert.AreEqual("Paris", withShows["address"]!["city"]!.GetValue<string>());

        Assert.AreEqual(HttpStatusCode.Conflict, (await Client.DeleteAsync($"/venues/{Id(venue)}")).StatusCode);
        await Book(Id(show));
        Assert.AreEqual(HttpStatusCode.Conflict, (await Client.DeleteAsync($"/shows/{Id(show)}")).StatusCode);

        var other = await CreateShow(Id(venue));
        Assert.AreEqual(HttpStatusCode.NoContent, (await Client.DeleteAsync($"/shows/{Id(other)}")).StatusCode);
        Assert.AreEqual(HttpStatusCode.NotFound, (await Client.GetAsync($"/shows/{Id(other)}")).StatusCode);
    }

    [TestMethod]
    public async Task Paging_And_Rights()
    {
        await CreateVenue("B");
        await CreateVenue("A");
        var page = (await Client.GetFromJsonAsync<JsonNode>("/venues?orderBy=Name&pageSize=1&descending=false"))!;
        Assert.AreEqual("A", page["items"]![0]!["name"]!.GetValue<string>());
        Assert.AreEqual(2, page["totalCount"]!.GetValue<int>());
        Assert.AreEqual(HttpStatusCode.BadRequest, (await Client.GetAsync("/venues?pageSize=0")).StatusCode);
        Assert.AreEqual(HttpStatusCode.BadRequest, (await Client.GetAsync("/venues?page=0")).StatusCode);
        Assert.AreEqual(HttpStatusCode.BadRequest, (await Client.GetAsync("/venues?orderBy=Nope")).StatusCode);

        AuthenticateAs();
        Assert.AreEqual(HttpStatusCode.OK, (await Client.GetAsync("/venues")).StatusCode);
        Assert.AreEqual(HttpStatusCode.Forbidden, (await Client.PostAsJsonAsync("/venues", new { name = "Z", address = Address(), capacity = 1 })).StatusCode);
        Assert.AreEqual(HttpStatusCode.Forbidden, (await Client.GetAsync("/bookings")).StatusCode);
        AuthenticateAs("ManageShows");
        Assert.AreEqual(HttpStatusCode.OK, (await Client.GetAsync("/bookings")).StatusCode);
        Unauthenticate();
        Assert.AreEqual(HttpStatusCode.Unauthorized, (await Client.GetAsync("/shows")).StatusCode);
    }
}

[TestClass]
public class JwtTests : ApiTestBase
{
    protected override bool UseTestAuthentication => false;

    protected override void ConfigureWebHost(Microsoft.AspNetCore.Hosting.IWebHostBuilder builder) =>
        builder.UseSetting("Jwt:Key", "short-key");

    private static string Token(string key, DateTime expires, params string[] rights)
    {
        var bytes = System.Text.Encoding.UTF8.GetBytes(key.PadRight(32));
        var descriptor = new Microsoft.IdentityModel.Tokens.SecurityTokenDescriptor
        {
            Claims = new Dictionary<string, object> { ["right"] = rights },
            NotBefore = expires.AddHours(-2),
            Expires = expires,
            SigningCredentials = new(new Microsoft.IdentityModel.Tokens.SymmetricSecurityKey(bytes), Microsoft.IdentityModel.Tokens.SecurityAlgorithms.HmacSha256),
        };
        return new Microsoft.IdentityModel.JsonWebTokens.JsonWebTokenHandler().CreateToken(descriptor);
    }

    private async Task<HttpStatusCode> Get(string uri, string? token)
    {
        var request = new HttpRequestMessage(HttpMethod.Get, uri);
        if (token is not null) request.Headers.Authorization = new("Bearer", token);
        return (await Client.SendAsync(request)).StatusCode;
    }

    [TestMethod]
    public async Task Tokens()
    {
        Assert.AreEqual(HttpStatusCode.Unauthorized, await Get("/venues", null));
        Assert.AreEqual(HttpStatusCode.Unauthorized, await Get("/venues", Token("other", DateTime.UtcNow.AddHours(1))));
        Assert.AreEqual(HttpStatusCode.Unauthorized, await Get("/venues", Token("short-key", DateTime.UtcNow.AddHours(-1))));
        Assert.AreEqual(HttpStatusCode.OK, await Get("/venues", Token("short-key", DateTime.UtcNow.AddHours(1))));
        Assert.AreEqual(HttpStatusCode.Forbidden, await Get("/bookings", Token("short-key", DateTime.UtcNow.AddHours(1))));
        Assert.AreEqual(HttpStatusCode.OK, await Get("/bookings", Token("short-key", DateTime.UtcNow.AddHours(1), "ManageShows")));
        Assert.AreEqual(HttpStatusCode.OK, await Get("/bookings", Token("short-key", DateTime.UtcNow.AddHours(1), "*")));
    }
}
